use crate::SendFrame;

use h2::frame::{self, Frame};
use h2::proto::Error;
use h2::SendError;

use futures::future::poll_fn;
use futures::{ready, Stream, StreamExt};

use tokio::io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt, ReadBuf};

use super::assert::assert_frame_eq;
